import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import  Input  from '../components/Input';
import  Button  from '../components/ui/Button';
import { Card, CardContent, CardHeader, CardTitle } from '../components/ui/Card';
import { Badge } from '../components/ui/Badge';

import { select,SelectContent,SelectItem,SelectTi } from '../components/ui/select';

const OpportunitiesPage = () => {
  const [opportunities, setOpportunities] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedState, setSelectedState] = useState('');
  const [selectedSkill, setSelectedSkill] = useState('');
  const [states, setStates] = useState([]); // لملء قائمة الولايات
  const [skills, setSkills] = useState([]); // لملء قائمة المهارات
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    // هنا يجب أن تقوم بجلب الفرص المتاحة من الـ API
    // وأيضًا جلب قائمة الولايات والمهارات المتاحة للفلترة
    const fetchOpportunitiesData = async () => {
      try {
        setLoading(true);
        // مثال على جلب الفرص (يجب استبداله بنقطة النهاية الفعلية)
        const opportunitiesResponse = await fetch('/api/opportunities');
        if (!opportunitiesResponse.ok) {
          throw new Error(`HTTP error! status: ${opportunitiesResponse.status}`);
        }
        const opportunitiesData = await opportunitiesResponse.json();
        setOpportunities(opportunitiesData);

        // مثال على جلب الولايات (يجب استبداله بنقطة النهاية الفعلية)
        const statesResponse = await fetch('/api/states');
        if (!statesResponse.ok) {
          throw new Error(`HTTP error! status: ${statesResponse.status}`);
        }
        const statesData = await statesResponse.json();
        setStates(statesData);

        // مثال على جلب المهارات (يجب استبداله بنقطة النهاية الفعلية)
        const skillsResponse = await fetch('/api/skills');
        if (!skillsResponse.ok) {
          throw new Error(`HTTP error! status: ${skillsResponse.status}`);
        }
        const skillsData = await skillsResponse.json();
        setSkills(skillsData);

      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchOpportunitiesData();
  }, []); // يتم تشغيله مرة واحدة عند تحميل المكون

  const filteredOpportunities = opportunities.filter((opportunity) => {
    const matchesSearchTerm = opportunity.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                              opportunity.company.toLowerCase().includes(searchTerm.toLowerCase()) ||
                              opportunity.description.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesState = selectedState ? opportunity.state === selectedState : true;

    const matchesSkill = selectedSkill ? opportunity.requiredSkills.includes(selectedSkill) : true;

    return matchesSearchTerm && matchesState && matchesSkill;
  });

  if (loading) {
    return <div className="flex justify-center items-center h-screen text-xl">جاري تحميل الفرص...</div>;
  }

  if (error) {
    return <div className="flex justify-center items-center h-screen text-red-500 text-xl">حدث خطأ: {error}</div>;
  }
    return (
    <div className="container mx-auto p-4">
      <h1 className="text-4xl font-bold text-center text-primary mb-8">الفرص المتاحة</h1>
      <div className="mb-6 flex flex-col md:flex-row gap-4">
        <Input
          type="text"
          placeholder="ابحث عن فرص..."
          className="flex-grow p-2 border rounded-md"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
        <Select onValueChange={setSelectedState} value={selectedState}>
          <SelectTrigger className="w-full md:w-[200px]">
       

            <SelectValue placeholder="اختر الولاية" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="">كل الولايات</SelectItem>
            {states.map((state) => (
              <SelectItem key={state} value={state}>
                {state}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Select onValueChange={setSelectedSkill} value={selectedSkill}>
          <SelectTrigger className="w-full md:w-[200px]">
            <SelectValue placeholder="اختر المهارة" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="">كل المهارات</SelectItem>
            {skills.map((skill) => (
              <SelectItem key={skill} value={skill}>
                {skill}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredOpportunities.length > 0 ? (
          filteredOpportunities.map((opportunity) => (
            <Card key={opportunity.id} className="flex flex-col">
              <CardHeader>
                <CardTitle className="text-xl font-semibold text-primary">{opportunity.title}</CardTitle>
                <p className="text-sm text-muted-foreground">{opportunity.company} - {opportunity.state}</p>
              </CardHeader>
              <CardContent className="flex-grow flex flex-col justify-between">
                <p className="text-gray-700 mb-4 line-clamp-3">{opportunity.description}</p>
                <div className="mb-4">
                  {opportunity.requiredSkills.map((skill) => (
                    <Badge key={skill} variant="secondary" className="mr-2 mb-2">
                      {skill}
                    </Badge>
                  ))}
                </div>
                <Link to={`/opportunities/${opportunity.id}`} className="block mt-auto">
                  <Button className="w-full">عرض التفاصيل</Button>
                </Link>
              </CardContent>
            </Card>
          ))
        ) : (
          <p className="col-span-full text-center text-lg text-gray-600">لا توجد فرص مطابقة لمعايير البحث.</p>
        )}
      </div>
    </div>
  );
};

export default OpportunitiesPage;
